import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BZRC44LV.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}'),r={name:"guide/settings.md"};function n(i,e,c,h,l,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Press <code>Mod</code> <code>,</code> to open the settings. Everything you change applies at once, in every tab, and stays after a restart: there is nothing to save and no need to start Blank again. Close them with <strong>Close</strong> or <code>Esc</code>.</p><p>The sections are listed on the left; <code>↑</code> and <code>↓</code> move between them, and the settings open again on the section you saw last.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><ul><li><strong>Theme:</strong> click a card to switch to that <a href="./themes">theme</a>. Each card shows the theme&#39;s own colors.</li><li><strong>In focus mode, hide the controls:</strong> when <a href="./writing#focus-mode">focus mode</a> lets the bars fade. They always fade when you type; choose whether they also fade after the mouse has rested for 3 or 10 seconds.</li></ul><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to &quot;Writing&quot;">​</a></h2><ul><li><strong>Autocorrect:</strong> one switch for each group of <a href="./autocorrect">autocorrect</a>, from arrows and dashes to links.</li><li><strong>Your replacements:</strong> click <strong>Edit…</strong> to add text that Blank replaces for you, such as <code>btw</code> → <code>by the way</code>, for every language or only the current one. <code>Esc</code> or <strong>Back</strong> brings you back.</li><li><strong>Indent size:</strong> how many spaces <code>Tab</code> indents a line of a <a href="./writing#code">code block</a> by, from 1 to 16.</li></ul><h2 id="spelling" tabindex="-1">Spelling <a class="header-anchor" href="#spelling" aria-label="Permalink to &quot;Spelling&quot;">​</a></h2><ul><li><strong>Check spelling</strong> turns <a href="./spelling">spell check</a> on or off, like <code>Mod</code> <code>Alt</code> <code>S</code>.</li><li><strong>Language</strong> chooses the language of spell check and autocorrect, like <code>Mod</code> <code>Alt</code> <code>L</code>.</li><li><strong>Ignore words in capitals</strong> and <strong>Ignore words with numbers</strong> leave words like <em>NASA</em> or <em>mp3</em> alone. The text is checked again as soon as you change them.</li><li><strong>Your dictionary:</strong> click <strong>Edit…</strong> to see the words you added in the current language, add new ones and remove others. Underlines go and come at once.</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Every command, with its shortcut. Search for one, click its shortcut and press the new keys. See <a href="./shortcuts#change-a-shortcut">Change a shortcut</a>.</p><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Blank&#39;s version, its license, links to the website and the source code, and the licenses of the software Blank is built with.</p><h2 id="where-the-settings-are-kept" tabindex="-1">Where the settings are kept <a class="header-anchor" href="#where-the-settings-are-kept" aria-label="Permalink to &quot;Where the settings are kept&quot;">​</a></h2><p>The theme, the language and whether spell check is on are kept with your documents. Everything else is written to <a href="./configuration">blank.json</a>, which only holds what you changed. You can still edit that file by hand; then restart Blank to use what you wrote.</p>',15)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
